<?php
namespace App\Filament\Resources\MediaAssetResource\Pages;
use App\Filament\Resources\MediaAssetResource; use App\Services\WebEmbedService; use Filament\Actions; use Filament\Resources\Pages\EditRecord;
class EditMediaAsset extends EditRecord { protected static string $resource=MediaAssetResource::class; protected function getHeaderActions():array{return[Actions\DeleteAction::make()->visible(fn()=>!$this->record->in_use)];} protected function mutateFormDataBeforeSave(array $data):array{unset($data['storage_path'],$data['original_filename']);if($this->record->media_type==='web_embed'&&isset($data['embed_url'])){$validated=app(WebEmbedService::class)->validateUrl($data['embed_url']);$data['embed_url']=$validated['url'];$data['validation_status']='pending';$data['validation_message']='Pendiente de comprobación en navegador.';}return $data;} }
